#include "../../framework/unity.h"
#include "../../../kernel/x509_der.h"
#include "x509_trust_vectors.inc"
#include "x509_intermediate_vectors.inc"
static const uint8_t certificate[]={0x30,0x4b,0x30,0x40,0x02,0x01,0x01,0x30,0x03,0x06,0x01,0x2a,0x30,0x00,0x30,0x1e,0x17,0x0d,'2','6','0','1','0','1','0','0','0','0','0','0','Z',0x17,0x0d,'2','7','0','1','0','1','0','0','0','0','0','0','Z',0x30,0x00,0x30,0x12,0x30,0x03,0x06,0x01,0x2a,0x03,0x0b,0x00,0x30,0x08,0x02,0x01,0x01,0x02,0x03,0x01,0x00,0x01,0x30,0x03,0x06,0x01,0x2a,0x03,0x02,0x00,0x00};
static const uint8_t hostname_certificate[]={0x30,0x81,0x84,0x30,0x79,0x02,0x01,0x01,0x30,0x03,0x06,0x01,0x2a,0x30,0x00,0x30,0x1e,0x17,0x0d,'2','6','0','1','0','1','0','0','0','0','0','0','Z',0x17,0x0d,'2','7','0','1','0','1','0','0','0','0','0','0','Z',0x30,0x18,0x31,0x16,0x30,0x14,0x06,0x03,0x55,0x04,0x03,0x0c,0x0d,'w','r','o','n','g','.', 'e','x','a','m','p','l','e',0x30,0x12,0x30,0x03,0x06,0x01,0x2a,0x03,0x0b,0x00,0x30,0x08,0x02,0x01,0x01,0x02,0x03,0x01,0x00,0x01,0xa3,0x1f,0x30,0x1d,0x30,0x1b,0x06,0x03,0x55,0x1d,0x11,0x04,0x14,0x30,0x12,0x82,0x10,'a','p','i','.', 'e','x','a','m','p','l','e','.', 't','e','s','t',0x30,0x03,0x06,0x01,0x2a,0x03,0x02,0x00,0x00};
void test_der_tlv_bounds(void){der_tlv_view_t view;uint8_t short_tlv[]={0x02,0x01,0x01},bad[]={0x30,0x82,0x01};TEST_ASSERT_EQUAL(0,der_tlv_parse(short_tlv,sizeof(short_tlv),&view));TEST_ASSERT_EQUAL(0x02,view.tag);TEST_ASSERT_EQUAL(1,view.length);TEST_ASSERT_EQUAL(3,view.total_length);TEST_ASSERT_NOT_EQUAL(0,der_tlv_parse(bad,sizeof(bad),&view));}
void test_x509_minimal_rsa_view(void){x509_certificate_view_t view;TEST_ASSERT_EQUAL(0,x509_certificate_parse(certificate,sizeof(certificate),&view));TEST_ASSERT_EQUAL(sizeof(certificate),view.certificate_length);TEST_ASSERT_EQUAL(1,view.serial_length);TEST_ASSERT_EQUAL(1,view.serial[0]);TEST_ASSERT_EQUAL(13,view.not_before_length);TEST_ASSERT_EQUAL('2',view.not_before[0]);TEST_ASSERT_EQUAL(1,view.rsa_modulus_length);TEST_ASSERT_EQUAL(1,view.rsa_modulus[0]);TEST_ASSERT_EQUAL(3,view.rsa_exponent_length);TEST_ASSERT_EQUAL(1,view.rsa_exponent[0]);TEST_ASSERT_EQUAL(1,view.rsa_exponent[2]);TEST_ASSERT_NOT_EQUAL(0,x509_rsa_public_key_validate(&view));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_parse(certificate,sizeof(certificate)-1U,&view));}
void test_x509_rsa_key_validation(void){static const uint8_t oid[]={0x06,0x09,0x2a,0x86,0x48,0x86,0xf7,0x0d,0x01,0x01,0x01,0x05,0x00},modulus[]={0x01},exponent[]={0x01,0x00,0x01};x509_certificate_view_t view={0};view.subject_public_key_algorithm=oid;view.subject_public_key_algorithm_length=sizeof(oid);view.rsa_modulus=modulus;view.rsa_modulus_length=sizeof(modulus);view.rsa_exponent=exponent;view.rsa_exponent_length=sizeof(exponent);TEST_ASSERT_EQUAL(0,x509_rsa_public_key_validate(&view));view.rsa_exponent=(const uint8_t[]){0x02};view.rsa_exponent_length=1;TEST_ASSERT_NOT_EQUAL(0,x509_rsa_public_key_validate(&view));}
void test_x509_hostname_cn_san_and_wildcard(void){x509_certificate_view_t view;static const uint8_t wildcard[]={ '*','.', 'e','x','a','m','p','l','e','.', 't','e','s','t'};TEST_ASSERT_EQUAL(0,x509_certificate_parse(hostname_certificate,sizeof(hostname_certificate),&view));TEST_ASSERT_EQUAL(13,view.common_name_length);TEST_ASSERT_EQUAL('w',view.common_name[0]);TEST_ASSERT_EQUAL(18,view.subject_alt_names_length);TEST_ASSERT_EQUAL(0,x509_certificate_hostname_validate(&view,"API.EXAMPLE.TEST"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_hostname_validate(&view,"wrong.example"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_hostname_validate(&view,"a.api.example.test"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_hostname_validate(&view,"api.example.test."));view.subject_alt_names=0;view.subject_alt_names_length=0U;TEST_ASSERT_EQUAL(0,x509_certificate_hostname_validate(&view,"WRONG.EXAMPLE"));view.common_name=wildcard;view.common_name_length=sizeof(wildcard);TEST_ASSERT_EQUAL(0,x509_certificate_hostname_validate(&view,"api.example.test"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_hostname_validate(&view,"a.api.example.test"));}
void test_x509_validity_dates(void){x509_certificate_view_t view;TEST_ASSERT_EQUAL(0,x509_certificate_parse(certificate,sizeof(certificate),&view));TEST_ASSERT_EQUAL(0,x509_certificate_valid_at(&view,"20260601000000Z"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_valid_at(&view,"20250101000000Z"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_valid_at(&view,"20280101000000Z"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_valid_at(&view,"20260230000000Z"));}
void test_x509_chain_one_anchor_rsa_sha256(void){x509_certificate_view_t root,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_root_der,sizeof(trust_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_leaf_der,sizeof(trust_leaf_der),&leaf));TEST_ASSERT_EQUAL(129,root.rsa_modulus_length);TEST_ASSERT_EQUAL(128,leaf.signature_length);TEST_ASSERT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,224U));root.subject_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,224U));root.subject_length++;leaf.signature_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,224U));}
void test_x509_tls_identity_policy(void){x509_certificate_view_t root,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_root_der,sizeof(trust_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_leaf_der,sizeof(trust_leaf_der),&leaf));TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20260818000000Z",workspace,224U));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"wrong.example.test","20260818000000Z",workspace,224U));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20250101000000Z",workspace,224U));}
void test_x509_chain_two_intermediate_rsa_sha256(void){x509_certificate_view_t root,intermediate,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_root_der,sizeof(aos417_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_int_der,sizeof(aos417_int_der),&intermediate));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_leaf_der,sizeof(aos417_leaf_der),&leaf));TEST_ASSERT_EQUAL(1U,intermediate.basic_constraints_present);TEST_ASSERT_EQUAL(1U,intermediate.basic_constraints_ca);TEST_ASSERT_EQUAL(1U,intermediate.key_usage_present);TEST_ASSERT_EQUAL(1U,intermediate.key_usage_key_cert_sign);TEST_ASSERT_EQUAL(0U,leaf.basic_constraints_ca);TEST_ASSERT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));{uint8_t root_path_present=root.path_len_present;uint32_t root_path=root.path_len_constraint;root.path_len_present=1U;root.path_len_constraint=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));root.path_len_present=root_path_present;root.path_len_constraint=root_path;}intermediate.basic_constraints_ca=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));intermediate.basic_constraints_ca=1U;intermediate.key_usage_key_cert_sign=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));intermediate.key_usage_key_cert_sign=1U;TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate_two(&leaf,&intermediate,&root,"api.example.test","20260819000000Z",workspace,224U));intermediate.subject_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));intermediate.subject_length++;intermediate.signature_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));}

void test_x509_rejects_unknown_critical_extension(void){uint8_t altered[sizeof(aos417_root_der)];x509_certificate_view_t view;uint32_t i;uint8_t found=0U;for(i=0U;i<sizeof(altered);i++)altered[i]=aos417_root_der[i];for(i=0U;i+5U<sizeof(altered);i++){if(altered[i]==0x55U&&altered[i+1U]==0x1dU&&altered[i+2U]==0x0fU&&altered[i+3U]==0x01U&&altered[i+4U]==0x01U&&altered[i+5U]==0xffU){altered[i+2U]=0x7eU;found=1U;break;}}TEST_ASSERT_EQUAL(1U,found);TEST_ASSERT_NOT_EQUAL(0,x509_certificate_parse(altered,sizeof(altered),&view));}

int main(void){unity_init();RUN_TEST(test_der_tlv_bounds);RUN_TEST(test_x509_minimal_rsa_view);RUN_TEST(test_x509_rsa_key_validation);RUN_TEST(test_x509_hostname_cn_san_and_wildcard);RUN_TEST(test_x509_validity_dates);RUN_TEST(test_x509_chain_one_anchor_rsa_sha256);RUN_TEST(test_x509_tls_identity_policy);RUN_TEST(test_x509_chain_two_intermediate_rsa_sha256);RUN_TEST(test_x509_rejects_unknown_critical_extension);unity_print_results();unity_cleanup();return unity_stats.tests_failed==0?0:1;}
